events.program:
def compute(vars):
    shares_2016 = vars["v1"]
    price_2016 = vars["v2"]
    shares_2017 = vars["v3"]
    price_2017 = vars["v4"]

    total_value_2016 = shares_2016 * price_2016
    total_value_2017 = shares_2017 * price_2017
    increase = total_value_2017 - total_value_2016

    return {
        "value": increase,
        "trace": {
            "total_value_2016": total_value_2016,
            "total_value_2017": total_value_2017,
            "increase": increase,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "currency"
            }
        }
    }
